const item = $input.first().json;
const original = $('Code: Parse & Filter').first().json;
logger.warn(`[alice-dms-thumbnailer] Generation failed for: ${original.weaviate_uuid} ${original.file_path} Status: ${item.statusCode}`);
return [{ json: { error: 'thumbnail_generation_failed', weaviate_uuid: original.weaviate_uuid, file_path: original.file_path, status_code: item.statusCode } }];
